fixtures.src/docs/types.ts:
export type HttpMethod = "GET" | "POST" | "PUT" | "DELETE" | "PATCH";

export interface ParameterSchema {
  readonly name: string;
  readonly in: "path" | "query" | "header";
  readonly required: boolean;
  readonly type: "string" | "number" | "integer" | "boolean";
  readonly description?: string;
}

export interface ResponseSchemaDefinition {
  readonly statusCode: number;
  readonly description: string;
  readonly schema?: Record<string, unknown>;
}

export interface RouteMetadata {
  readonly path: string;
  readonly method: HttpMethod;
  readonly summary: string;
  readonly description: string;
  readonly tags: readonly string[];
  readonly parameters: readonly ParameterSchema[];
  readonly requestBodySchema?: Record<string, unknown>;
  readonly responses: readonly ResponseSchemaDefinition[];
  readonly security: readonly string[];
}

export interface OpenApi31Spec {
  readonly openapi: "3.1.0";
  readonly info: {
    readonly title: string;
    readonly version: string;
    readonly description?: string;
  };
  readonly paths: Record<string, Record<string, unknown>>;
  readonly components?: {
    readonly schemas?: Record<string, unknown>;
    readonly securitySchemes?: Record<string, unknown>;
  };
}

export interface AdrDocument {
  readonly id: string;
  readonly title: string;
  readonly status: "Draft" | "Proposed" | "Accepted" | "Superseded" | "Rejected";
  readonly context: string;
  readonly decision: string;
  readonly consequences: {
    readonly positive: readonly string[];
    readonly negative: readonly string[];
  };
  readonly author: string;
  readonly date: string;
}

