import type { RouteMetadata } from "./types.js";
import { SAMPLE_API_ROUTES } from "../sample-api/routes.js";

export class ApiMetadataExtractor {
  public extractRoutes(): readonly RouteMetadata[] {
    return SAMPLE_API_ROUTES;
  }

  public filterByTag(tag: string): readonly RouteMetadata[] {
    return SAMPLE_API_ROUTES.filter((r) => r.tags.includes(tag));
  }
}

